<script lang="ts">import Icon from '$lib/components/Icon.svelte';import {mailState,mailCommand,mailId} from '$lib/mail/store';import {address} from '$lib/mail/model.js';export let domains:string[];let show=false,local='',domain='',to='',error='';$: if(!domains.includes(domain))domain=domains[0]||'';function add(){try{mailCommand({type:'forward-add',id:mailId(),local,domain,to});local='';to='';show=false;error='';}catch(e){error=e instanceof Error?e.message:'Forwarder creation failed.';}}function remove(id:string){if(!window.confirm('Remove this sample forwarder?'))return;try{mailCommand({type:'forward-remove',id});error='';}catch(e){error=e instanceof Error?e.message:'Removal failed.';}}</script>
<div class="stack"><section class="card table-card"><div class="table-head"><div class="row between wrap"><div><h3>Forwarders</h3><p class="subtitle">Redirect incoming mail to another address. No mailbox needed.</p></div><button class="btn primary" on:click={()=>show=!show}><Icon name="Plus"/>Add forwarder</button></div></div><div class="table-wrap"><table><thead><tr><th>Address</th><th>Forward to</th><th></th></tr></thead><tbody>{#each $mailState.forwarders as f}<tr><td class="native-path">{address(f)}</td><td class="native-path">{f.to}</td><td><button class="btn danger small" on:click={()=>remove(f.id)}>Remove</button></td></tr>{:else}<tr><td colspan="3">No forwarders yet.</td></tr>{/each}</tbody></table></div></section>{#if show}{#if domains.length}<form class="card stack" on:submit|preventDefault={add}><h3>Add forwarder</h3><div class="mail-address-fields"><label class="field">Address name<input required bind:value={local} maxlength="64" placeholder="sales"/></label><span class="mail-at">@</span><label class="field">Domain<select bind:value={domain}>{#each domains as d}<option>{d}</option>{/each}</select></label></div><label class="field">Forward to<input type="email" required bind:value={to} placeholder="name@example.net"/></label><small>Forwarding rules are saved locally. No mail is redirected.</small><div class="native-actions"><button type="button" class="btn secondary" on:click={()=>show=false}>Cancel</button><button type="submit" class="btn primary">Add forwarder</button></div></form>{:else}<a href="/domains" class="btn secondary">Add a domain first</a>{/if}{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</div>
